import React from "react";
import {Button} from "@mui/material";
import {Link, useParams} from "react-router-dom";
import {useGetServiceByIdQuery} from "./servicesApi";
import Loader from "../../ui/loader/loader";
import QueryError from "../shared/QueryError";
import CatalogCostCard from "../costing/CatalogCostCard";
import {money} from "../costing/types";
export default function ServiceDetails() {
    const {id} = useParams<{id: string}>(); const {data, isLoading, isError, error, refetch} = useGetServiceByIdQuery(id!, {skip: !id});
    if (isLoading) return <Loader/>; if (isError) return <div className="cost-page"><QueryError error={error} onRetry={refetch}/></div>; if (!data) return null;
    return <><div className="cost-page"><header className="cost-header"><div><span className="cost-eyebrow">Каталог / карточка услуги</span><h1>{data.name}</h1><p>{data.description}</p></div><div className="cost-actions"><Button component={Link} to="/servicesManagement">Все услуги</Button><Button component={Link} to={`/servicesManagement/editService/${data.id}`} variant="contained">Редактировать</Button></div></header><section className="cost-panel"><h2>Цена: {money(data.price)} BYN</h2><table className="cost-table"><tbody>{Object.entries({...data.modifications, ...data.fields}).map(([key, value]) => <tr key={key}><td>{key}</td><td>{value}</td></tr>)}</tbody></table></section></div><CatalogCostCard itemType={1} itemId={data.id}/></>;
}
