export const categories = ["Материалы", "Труд", "Оборудование", "Подрядчики", "Доставка и закупка", "Производственные накладные", "Административные", "Коммерческие", "Прочие производственные", "Сверхнормативные потери"];
export const statuses = ["Черновик", "Утверждена", "Заменена новой версией", "Архив"];
export const allocationBases = ["Единицы выпуска", "Человеко-часы", "Машино-часы", "Стоимость материалов", "Стоимость труда", "Прямые затраты", "Операции / драйвер ABC"];
export type CatalogItem = {type: number; id: number; name: string; sellingPrice: number};
export type CostLine = {id: string; name: string; category: number; behavior: number; scope: number; quantity: number; unit: string; unitCost: number; exchangeRate: number; discountPercent: number; taxPercent: number; priceIncludesTax: boolean; recoverableTaxPercent: number; lossPercent: number; burdenPercent: number; source: number; resourceId?: string | null; componentType?: number | null; componentId?: number | null; sourceCalculationId?: string | null; sourceDescription?: string | null};
export type Overhead = {id: string; name: string; category: number; behavior: number; base: number; method: number; amount: number; normalCapacity: number; actualCapacity: number; driverQuantity: number};
export type CostInput = {currency: string; outputQuantity: number; outputLossPercent: number; sellingPrice: number; salesTaxPercent: number; sellingPriceIncludesTax: boolean; targetMarginPercent: number; laborHoursPerUnit: number; machineHoursPerUnit: number; lines: CostLine[]; overheads: Overhead[]};
export type Breakdown = {id: string; name: string; category: number; behavior: number; quantity: number; rate: number; total: number; recoverableTax: number; unallocatedOverhead: number; formula: string};
export type CostResult = {currency: string; goodOutputQuantity: number; directCost: number; productionCost: number; fullCost: number; variableCost: number; fixedCost: number; productionUnitCost: number; fullUnitCost: number; variableUnitCost: number; netSellingPrice: number; profitPerUnit: number; marginPercent: number | null; markupPercent: number | null; suggestedNetPrice: number; suggestedGrossPrice: number; breakEvenQuantity: number | null; recoverableTax: number; unallocatedOverhead: number; breakdown: Breakdown[]; categories: {category: number; total: number; perUnit: number; sharePercent: number}[]; warnings: string[]};
export type CostEvent = {at: string; actor: string; action: string; note: string};
export type Calculation = {id: string; firmId: number; itemType: number; itemId: number; itemName: string; name: string; notes: string; version: number; kind: number; status: number; baselineId: string | null; createdAt: string; updatedAt: string; approvedAt: string | null; approvedBy: string | null; stamp: string; snapshot: {input: CostInput; result: CostResult}; events: CostEvent[]};
export type Resource = {id: string; name: string; unit: string; currency: string; category: number; unitCost: number; notes: string; stamp: string; updatedAt: string; events: CostEvent[]};
export type CostSummary = {item: CatalogItem; approved: Calculation | null; hasDraft: boolean; profitPerUnit: number | null; marginPercent: number | null};
export type Comparison = {plannedId: string; actualId: string; currency: string; plannedUnitCost: number; actualUnitCost: number; unitVariance: number; unitVariancePercent: number | null; lines: {lineId: string; name: string; planned: number; actual: number; variance: number; percent: number | null}[]};
export const emptyInput = (): CostInput => ({currency: "BYN", outputQuantity: 1, outputLossPercent: 0, sellingPrice: 0, salesTaxPercent: 0, sellingPriceIncludesTax: false, targetMarginPercent: 30, laborHoursPerUnit: 0, machineHoursPerUnit: 0, lines: [], overheads: []});
export const newLine = (category = 0): CostLine => ({id: crypto.randomUUID(), name: "", category, behavior: 0, scope: 0, quantity: 1, unit: category === 1 ? "час" : "шт", unitCost: 0, exchangeRate: 1, discountPercent: 0, taxPercent: 0, priceIncludesTax: false, recoverableTaxPercent: 100, lossPercent: 0, burdenPercent: 0, source: 0});
export const newOverhead = (): Overhead => ({id: crypto.randomUUID(), name: "", category: 5, behavior: 1, base: 0, method: 0, amount: 0, normalCapacity: 0, actualCapacity: 0, driverQuantity: 0});
export const money = (value: number | null | undefined, digits = 2) => value == null ? "—" : value.toLocaleString("ru-RU", {minimumFractionDigits: digits, maximumFractionDigits: digits});
