import React from "react";
import {Alert, Button, Chip} from "@mui/material";
import {Link} from "react-router-dom";
import {useAuth} from "../../auth/AuthContext";
import {useCatalogCostQuery} from "./costingApi";
import {money} from "./types";
import QueryError from "../shared/QueryError";
import "./costing.css";

function Card({itemType, itemId}: {itemType: number; itemId: number}) {
    const {data, isLoading, isError, error, refetch} = useCatalogCostQuery({itemType, itemId});
    return <section className="cost-panel cost-card"><div className="cost-header"><h2>Нормативная себестоимость {itemType === 0 ? "товара" : "услуги"}</h2><Button component={Link} to={`/costing/new?itemType=${itemType}&itemId=${itemId}`}>Новая калькуляция</Button></div>
        {isLoading ? <p>Загрузка себестоимости…</p> : isError ? <QueryError error={error} onRetry={refetch}/> : data?.approved ? <><div className="cost-stats"><div className="cost-stat"><span>Производственная / ед.</span><strong>{money(data.approved.snapshot.result.productionUnitCost)}</strong><small>{data.approved.snapshot.input.currency}</small></div><div className="cost-stat"><span>Полная / ед.</span><strong>{money(data.approved.snapshot.result.fullUnitCost)}</strong><small>{data.approved.snapshot.input.currency}</small></div><div className={`cost-stat ${(data.profitPerUnit ?? 0) < 0 ? "negative" : ""}`}><span>Прибыль по текущей цене</span><strong>{money(data.profitPerUnit)}</strong><small>Маржа {money(data.marginPercent)}%</small></div></div><div className="cost-actions" style={{marginTop: 16}}><Chip size="small" color="success" label={`Утверждена · v${data.approved.version}`}/><span className="cost-note">{data.approved.approvedBy} · {new Date(data.approved.approvedAt!).toLocaleDateString("ru-RU")}</span><Button component={Link} to={`/costing/${data.approved.id}`}>Открыть расчёт</Button>{data.hasDraft && <Chip size="small" label="Есть черновик"/>}</div>{data.approved.snapshot.input.currency !== "BYN" && <Alert sx={{mt: 2}} severity="info">Себестоимость в другой валюте. Прибыль по цене каталога BYN не сравнивается.</Alert>}</> : <div className="cost-empty"><strong>Нормативный расчёт ещё не утверждён</strong><span>{data?.hasDraft ? "Есть черновик. Утвердите нормативную версию, чтобы показать её в карточке." : "Добавьте материалы, труд и накладные расходы в калькуляцию этой позиции."}</span></div>}
    </section>;
}
export default function CatalogCostCard(props: {itemType: number; itemId: number}) {const {isCompanyAdmin, isSuperAdmin} = useAuth(); return isCompanyAdmin || isSuperAdmin ? <Card {...props}/> : null;}
